/* prog56_kruskal_mst.c
 * Re‑implementation of the original obfuscated binary.
 * Behaviour:
 *   ./prog56_kruskal_mst N
 *   reads up to 9 edges (u v w) from stdin,
 *   runs Kruskal, prints the MST weight and edges or
 *   "DISCONNECTED"/"INVALID_ARGS".
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_VERTICES 6          /* same limit as the original binary */
#define MAX_EDGES    9          /* same limit as the original binary */

typedef struct {
    int u, v;
    int w;
} Edge;

/* ---------- Union‑Find (Disjoint Set) ---------- */
static int parent[MAX_VERTICES];

static void uf_init(int n) {
    for (int i = 0; i < n; ++i) parent[i] = i;
}

static int uf_find(int x) {
    if (parent[x] != x) parent[x] = uf_find(parent[x]);
    return parent[x];
}

static void uf_union(int a, int b) {
    int ra = uf_find(a);
    int rb = uf_find(b);
    if (ra != rb) parent[ra] = rb;
}

/* ---------- Helper: read a single edge ---------- */
static int read_edge(Edge *e) {
    return scanf("%d %d %d", &e->u, &e->v, &e->w) == 3;
}

/* ---------- Main ---------- */
int main(int argc, char **argv) {
    /* ----- argument handling ----- */
    if (argc < 2) {
        puts("INVALID_ARGS");
        return 0;
    }

    char *endptr;
    long n_long = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || n_long <= 0 || n_long > MAX_VERTICES) {
        puts("INVALID_ARGS");
        return 0;
    }
    int n = (int)n_long;               /* number of vertices */

    /* ----- read edges (max 9) ----- */
    Edge edges[MAX_EDGES];
    int edge_cnt = 0;
    while (edge_cnt < MAX_EDGES && read_edge(&edges[edge_cnt])) {
        /* ignore edges that refer to non‑existent vertices */
        if (edges[edge_cnt].u >= 0 && edges[edge_cnt].u < n &&
            edges[edge_cnt].v >= 0 && edges[edge_cnt].v < n) {
            ++edge_cnt;
        }
        /* otherwise simply discard the malformed line */
    }

    /* ----- Kruskal ----- */
    /* sort edges by weight (simple insertion sort – data set is tiny) */
    for (int i = 1; i < edge_cnt; ++i) {
        Edge key = edges[i];
        int j = i - 1;
        while (j >= 0 && edges[j].w > key.w) {
            edges[j + 1] = edges[j];
            --j;
        }
        edges[j + 1] = key;
    }

    uf_init(n);

    Edge mst[MAX_VERTICES - 1];   /* at most n‑1 edges in an MST */
    int mst_cnt = 0;
    int total_weight = 0;

    for (int i = 0; i < edge_cnt && mst_cnt < n - 1; ++i) {
        int ru = uf_find(edges[i].u);
        int rv = uf_find(edges[i].v);
        if (ru != rv) {
            uf_union(ru, rv);
            mst[mst_cnt++] = edges[i];
            total_weight += edges[i].w;
        }
    }

    /* ----- output ----- */
    if (mst_cnt == n - 1) {
        printf("weight=%d edges=", total_weight);
        for (int i = 0; i < mst_cnt; ++i) {
            if (i > 0) putchar(',');
            printf("%d-%d", mst[i].u, mst[i].v);
        }
        putchar('\n');
    } else {
        puts("DISCONNECTED");
    }

    return 0;
}
